import {esc,icon,download} from './ui.mjs';
import {keys,list,write,hasDraftScope,captureDraftScope} from './state.mjs';
import {validateFormulaCode} from './research-delivery-model.mjs';
import {formulaTemplates,formulaSubjects,formulaSymbolGroups,filterFormulaTemplates,insertFormulaToken} from './research-formula-catalog.mjs';
import {mountFormulaOcr} from './formula-ocr.mjs';

export const formulaStudioDraftKey='paperknow-formula-studio-draft-v1';
export function mountResearchFormulaStudio({container,ctx={},initialFormula,initialId=null,initialRequirements='',onChange=()=>{},loadRenderer=()=>import('./assets/research-formula.js'),downloadFile=download,mountOcr=mountFormulaOcr}={}){
 if(!container)throw Error('缺少公式编辑区域。');
 const doc=container.ownerDocument,win=doc.defaultView,scope=captureDraftScope(),scoped=hasDraftScope();
 if(!doc.querySelector('link[data-formula-studio-style]')){const style=doc.createElement('link');style.rel='stylesheet';style.href='/workspace/research-formula-studio.css';style.dataset.formulaStudioStyle='';doc.head.append(style);}
 let cached={};if(!scoped){try{const parsed=JSON.parse(win.localStorage.getItem(formulaStudioDraftKey)||'{}');if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))cached=parsed;}catch{}}
 let formula=String(initialFormula??cached.formula??'').slice(0,2000),formulaId=initialId||(initialFormula===undefined?cached.formulaId:null)||null,requirements=String(initialRequirements||(initialFormula===undefined?cached.requirements:'')||'').slice(0,2000),alive=true,sequence=0,timer=null,svg='',renderer=null,subject='all',level='all',category='all',query='',symbolGroup='common',templateTab='templates',font='standard',size=32,ink='#203659',ocr=null,job=null,aiState={},busy=false,savedFormula=formula;
 if(!scoped&&cached.formula===formula&&cached.requirements===requirements&&cached.aiState&&typeof cached.aiState==='object'&&!Array.isArray(cached.aiState))aiState=cached.aiState;
 const undoStack=[],redoStack=[],recent=[],current=()=>alive&&container.isConnected&&scope.isCurrent(),$=s=>container.querySelector(s),state=()=>({formula,formulaId,requirements,aiState:job?.getState?.()||aiState});
 const notify=message=>ctx.notify?.(message);
 function status(message,error=false){if(!current())return;const n=$('[data-fs-status]');n.textContent=message;n.classList.toggle('is-error',error);}
 function persist({strict=false}={}){if(!current())return;onChange(state());if(scoped)return;try{win.localStorage.setItem(formulaStudioDraftKey,JSON.stringify({formula,formulaId,requirements,aiState}));status('草稿已自动保存在当前浏览器');}catch{status('浏览器暂时无法保存草稿，请及时复制或导出。',true);if(strict)throw Error('当前浏览器未能保存任务草稿，已停止提交，避免重复扣费。');}}
 function schedule(){win.clearTimeout(timer);timer=win.setTimeout(persist,350);}
 const button=(action,label,extra='')=>`<button type="button" class="fs-button" data-fs-action="${action}" ${extra}>${label}</button>`;
 container.innerHTML=`<div class="formula-studio"><aside class="fs-library" aria-label="公式模板查询"><div class="fs-library-title"><span class="fs-mini-icon">ƒₓ</span><div><h2>公式模板</h2><p>选取模板，在编辑器中继续修改</p></div></div><div class="fs-tabs" role="tablist" aria-label="模板类型"><button type="button" role="tab" aria-selected="true" data-fs-tab="templates">公式模板</button><button type="button" role="tab" aria-selected="false" data-fs-tab="recent">最近使用</button></div><div class="fs-filters"><label>学科<select data-fs-subject aria-label="筛选公式学科">${formulaSubjects.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label><label>程度<select data-fs-level aria-label="筛选公式程度"><option value="all">全部程度</option><option value="basic">基础公式</option><option value="advanced">进阶公式</option></select></label><label>分类<select data-fs-category aria-label="筛选公式分类"><option value="all">全部分类</option></select></label><label class="fs-search">${icon('search',16)}<input data-fs-search type="search" aria-label="搜索公式模板" placeholder="搜索名称、符号或关键词"></label></div><div class="fs-template-list" data-fs-templates></div><p class="fs-catalog-note" data-fs-catalog-note></p></aside><section class="fs-main" aria-label="公式工作区"><section class="fs-symbol-panel"><div class="fs-symbol-tabs" role="tablist" aria-label="公式符号分类">${formulaSymbolGroups.map((group,index)=>`<button type="button" role="tab" aria-selected="${index===0}" data-fs-group="${group.id}">${group.label}</button>`).join('')}</div><div class="fs-symbols" data-fs-symbols></div></section><section class="fs-editor-panel"><header class="fs-panel-title"><div><span class="fs-eyebrow">LATEX EDITOR</span><h2>公式编辑</h2></div><div class="fs-actions">${button('ocr',icon('upload',15)+' 图片识别','aria-expanded="false"')}${button('ai',icon('plus',15)+' AI 生成公式')}</div></header><div class="fs-ocr" data-fs-ocr hidden></div><div class="fs-ai-request" data-fs-ai-request hidden><label>描述你需要的公式<textarea data-fs-requirements maxlength="2000" rows="3" placeholder="例如：给出多元线性回归公式，并说明各个符号的含义。"></textarea></label><button type="button" class="btn primary" data-fs-action="ai-open">确认需求与费用 →</button><div data-fs-ai></div></div><div class="fs-toolbar" aria-label="公式编辑工具">${button('undo','↶ 撤销','aria-label="撤销公式修改" disabled')}${button('redo','↷ 重做','aria-label="重做公式修改" disabled')}${button('clear','清空')}<span class="fs-toolbar-separator"></span><label>字形<select data-fs-font aria-label="公式字形"><option value="standard">标准数学</option><option value="sans">无衬线</option><option value="bold">粗体数学</option></select></label><label>字号<select data-fs-size aria-label="公式预览字号"><option value="24">24</option><option value="32" selected>32</option><option value="40">40</option><option value="48">48</option></select></label><label>颜色<input data-fs-ink type="color" value="#203659" aria-label="公式颜色"></label></div><div class="fs-code-wrap"><textarea data-fs-editor maxlength="2000" spellcheck="false" aria-label="LaTeX 公式编辑器" placeholder="在此输入 LaTeX，或从左侧选择一个公式模板…"></textarea><span class="fs-count" data-fs-count>0 / 2000</span></div><footer class="fs-editor-footer"><span>${icon('help',14)} 符号和模板会插入到光标位置；可直接修改 LaTeX。</span>${button('copy','复制 LaTeX')}</footer></section><section class="fs-preview-panel"><header class="fs-panel-title"><div><span class="fs-eyebrow">LIVE PREVIEW</span><h2>公式预览</h2></div><span class="fs-live-label"><i></i> 实时排版</span></header><div class="fs-preview" data-fs-preview aria-label="公式 SVG 预览"><div class="fs-preview-empty"><span>∑</span><b>让公式清晰地呈现</b><p>选择模板或输入 LaTeX，即可查看排版效果</p></div></div><p class="fs-render-error" data-fs-error role="alert" hidden></p><div class="fs-export-bar"><span>透明矢量 SVG · 高清 PNG · LaTeX 源码</span><div class="fs-actions">${button('svg','导出 SVG')}${button('png','导出 PNG')}${button('txt','导出源码')}${button('copy-svg','复制 SVG')}<button type="button" class="btn primary" data-fs-action="save">${icon('check',15)} 保存公式</button></div></div></section><div class="fs-bottom-note"><p data-fs-status role="status" aria-live="polite">${scoped?'当前为账户成果编辑，修改后请保存到账户。':'公式在本地实时排版，手动编辑不扣科研积分。'}</p><span>公式条件与符号含义，请结合研究核对</span></div></section></div>`;
 const editor=$('[data-fs-editor]');editor.value=formula;$('[data-fs-requirements]').value=requirements;
 function historyButtons(){$('[data-fs-action="undo"]').disabled=!undoStack.length;$('[data-fs-action="redo"]').disabled=!redoStack.length;}
 function setFormula(value,{remember=true,selection=null}={}){if(!current())return;value=String(value).slice(0,2000);if(value===formula)return;if(remember){undoStack.push(formula);if(undoStack.length>100)undoStack.shift();redoStack.length=0;}formula=value;editor.value=value;historyButtons();$('[data-fs-count]').textContent=`${formula.length} / 2000`;if(selection){editor.focus({preventScroll:true});editor.setSelectionRange(selection.start,selection.end);}onChange(state());schedule();job?.inputChanged?.();void preview();}
 function insert(token){if(formula.length-(editor.selectionEnd-editor.selectionStart)+token.length>2000)return notify('公式最多支持 2000 字符，请先精简内容。');const next=insertFormulaToken(formula,token,editor.selectionStart,editor.selectionEnd);setFormula(next.value,{selection:next});}
 async function getSvg(){const checked=validateFormulaCode(formula),snapshot=formula,visual={font,ink};renderer||=await loadRenderer();if(!current()||snapshot!==formula||visual.font!==font||visual.ink!==ink)return null;const wrapped=font==='sans'?`\\mathsf{${checked}}`:font==='bold'?`\\boldsymbol{${checked}}`:checked;const markup=renderer.renderFormulaSvg(wrapped);const parsed=new win.DOMParser().parseFromString(markup,'image/svg+xml'),root=parsed.documentElement;if(root.localName!=='svg'||parsed.querySelector('parsererror'))throw Error('公式预览未能生成，请检查输入。');root.setAttribute('color',ink);root.setAttribute('aria-label',checked);return new win.XMLSerializer().serializeToString(root);}
 async function preview(){const ticket=++sequence;svg='';const target=$('[data-fs-preview]'),error=$('[data-fs-error]');error.hidden=true;error.textContent='';if(!formula.trim()){target.innerHTML='<div class="fs-preview-empty"><span>∑</span><b>让公式清晰地呈现</b><p>选择模板或输入 LaTeX，即可查看排版效果</p></div>';return;}try{const markup=await getSvg();if(!current()||ticket!==sequence||!markup)return;svg=markup;target.innerHTML=markup;target.style.setProperty('--formula-size',size+'px');}catch(e){if(!current()||ticket!==sequence)return;target.textContent='暂时无法排版，请根据下方提示修改公式。';error.textContent=e.message||'公式语法有误，请检查括号、上下标与命令。';error.hidden=false;}}
 function renderSymbols(){const group=formulaSymbolGroups.find(g=>g.id===symbolGroup);$('[data-fs-symbols]').innerHTML=group.tokens.map(([label,token],index)=>`<button type="button" data-fs-token="${index}" title="${esc(token)}" aria-label="插入${esc(label)}"><span>${esc(label)}</span><code>${esc(token)}</code></button>`).join('');}
 function renderTemplates(){const rows=templateTab==='recent'?recent.map(id=>formulaTemplates.find(row=>row.id===id)).filter(Boolean):filterFormulaTemplates({subject,level,category,query});const target=$('[data-fs-templates]');target.innerHTML=rows.length?rows.map(item=>`<button type="button" class="fs-template" data-fs-template="${item.id}" title="插入${esc(item.title)}"><span class="fs-template-head"><strong>${esc(item.title)}</strong><span>＋</span></span><span class="fs-template-equation" data-fs-template-preview="${item.id}">${esc(item.formula)}</span><small>${esc(item.description)}</small></button>`).join(''):`<div class="fs-template-empty">${templateTab==='recent'?'使用过的模板会出现在这里。':'没有匹配的模板，试试调整筛选或搜索词。'}</div>`;$('[data-fs-catalog-note]').textContent=templateTab==='recent'?`${rows.length} 个本次使用的模板`:`内置 ${formulaTemplates.length} 个常用模板 · 当前 ${rows.length} 个`;
  void (async()=>{try{renderer||=await loadRenderer();for(const item of rows){if(!current())return;const element=$(`[data-fs-template-preview="${item.id}"]`);if(!element||!element.isConnected)continue;try{element.innerHTML=renderer.renderFormulaSvg(item.formula);}catch{element.textContent=item.formula;}}}catch{}})();
 }
 function categories(){const values=[...new Set(formulaTemplates.filter(item=>subject==='all'||item.subject===subject).map(item=>item.category))];if(!values.includes(category))category='all';$('[data-fs-category]').innerHTML='<option value="all">全部分类</option>'+values.map(value=>`<option ${value===category?'selected':''}>${esc(value)}</option>`).join('');}
 function save(){validateFormulaCode(formula);if(!svg)throw Error('请先修正公式语法，排版成功后再保存。');const rows=list(keys.drafts),old=rows.find(row=>row.id===formulaId),now=new Date().toISOString();formulaId=old?.id||win.crypto.randomUUID();const item={...old,id:formulaId,tool:'research',kind:'科研公式',title:'科研公式 · '+formula.slice(0,35),createdAt:old?.createdAt||now,updatedAt:now,projectId:old?.projectId||'',text:formula,formula,requirements};write(keys.drafts,old?rows.map(row=>row.id===formulaId?item:row):[item,...rows]);savedFormula=formula;persist();status(scoped?'公式已保留在账户编辑区，请确认保存到账户。':'公式已保存到「我的成果」，可随时返回继续编辑。');notify(scoped?'公式已更新，请保存到账户。':'公式已保存到我的成果。');}
 async function exportFile(kind){const captured=state(),valid=()=>current()&&formula===captured.formula,owner=scope.ownerId;if(!formula.trim())throw Error('请先输入公式。');if(kind==='txt'){validateFormulaCode(captured.formula);if(valid())await downloadFile('PaperKnow-科研公式.tex',captured.formula,'text/plain;charset=utf-8',{expectedUserId:owner,sourceType:'research',sourceId:captured.formulaId||''});return;}const markup=await getSvg();if(!valid()||!markup)return;if(kind==='svg'){await downloadFile('PaperKnow-科研公式.svg',markup,'image/svg+xml;charset=utf-8',{expectedUserId:owner,sourceType:'research',sourceId:captured.formulaId||''});return;}if(kind==='copy-svg'){if(typeof win.navigator.clipboard?.writeText!=='function')throw Error('当前浏览器无法直接复制，请使用导出 SVG。');try{await win.navigator.clipboard.writeText(markup);}catch{throw Error('复制未成功，请使用导出 SVG。');}if(valid())notify('SVG 源码已复制。');return;}const url=win.URL.createObjectURL(new Blob([markup],{type:'image/svg+xml'}));try{const image=new win.Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('图片转换失败，请使用 SVG 导出。'));image.src=url;});if(!valid())return;const canvas=doc.createElement('canvas');canvas.width=2400;canvas.height=Math.max(200,Math.min(4800,Math.ceil(2400*image.naturalHeight/image.naturalWidth)));const context=canvas.getContext('2d');if(!context)throw Error('当前浏览器无法导出 PNG，请使用 SVG。');context.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!valid())return;if(!blob)throw Error('PNG 导出失败，请重试。');await downloadFile('PaperKnow-科研公式.png',blob,'image/png',{expectedUserId:owner,sourceType:'research',sourceId:captured.formulaId||''});}finally{win.URL.revokeObjectURL(url);}}
 async function openAI(){if(scoped)throw Error('请先保存当前账户成果，再从科研工具页面发起 AI 处理；当前公式仍可编辑和导出。');if(!requirements.trim())throw Error('请描述你需要的公式。');if(!job){const module=await import('./tool-job-panel.mjs');if(!current())return;job=module.mountToolJobPanel({container:$('[data-fs-ai]'),ctx,kind:'research',operation:'formula',initialState:aiState,isCurrent:current,getSnapshot:()=>({title:'科研公式',text:requirements,requirements:'请生成标准数学 LaTeX，并解释符号含义、适用条件。不得编造实验测量结果。当前公式：'+formula,language:'中文',mode:'formula',materials:[]}),onStateChange:value=>{aiState=value;persist({strict:true});},onApply:output=>{const next=validateFormulaCode(output.latex);setFormula(next);notify('公式已应用，请核对符号与适用条件。');}});}await job.open();}
 async function click(event){const template=event.target.closest('[data-fs-template]');if(template){const item=formulaTemplates.find(row=>row.id===template.dataset.fsTemplate);if(!item)return;insert(item.formula);const index=recent.indexOf(item.id);if(index>=0)recent.splice(index,1);recent.unshift(item.id);recent.splice(12);if(templateTab==='recent')renderTemplates();return;}const token=event.target.closest('[data-fs-token]');if(token){insert(formulaSymbolGroups.find(g=>g.id===symbolGroup).tokens[Number(token.dataset.fsToken)][1]);return;}const group=event.target.closest('[data-fs-group]');if(group){symbolGroup=group.dataset.fsGroup;container.querySelectorAll('[data-fs-group]').forEach(node=>node.setAttribute('aria-selected',String(node===group)));renderSymbols();return;}const tab=event.target.closest('[data-fs-tab]');if(tab){templateTab=tab.dataset.fsTab;container.querySelectorAll('[data-fs-tab]').forEach(node=>node.setAttribute('aria-selected',String(node===tab)));renderTemplates();return;}const target=event.target.closest('[data-fs-action]');if(!target||busy)return;try{switch(target.dataset.fsAction){case 'undo':if(undoStack.length){redoStack.push(formula);setFormula(undoStack.pop(),{remember:false});historyButtons();}break;case 'redo':if(redoStack.length){undoStack.push(formula);setFormula(redoStack.pop(),{remember:false});historyButtons();}break;case 'clear':setFormula('');break;case 'copy':if(!formula.trim())throw Error('请先输入公式。');if(typeof win.navigator.clipboard?.writeText!=='function')throw Error('当前浏览器无法自动复制，请在编辑器中手动复制。');try{await win.navigator.clipboard.writeText(formula);}catch{throw Error('复制未成功，请在编辑框中手动复制公式。');}if(current())notify('LaTeX 已复制。');break;case 'save':save();break;case 'ocr':{const panel=$('[data-fs-ocr]');panel.hidden=!panel.hidden;target.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden&&!ocr)ocr=mountOcr({container:panel,notify,onApply:value=>{if(current())setFormula(validateFormulaCode(value));}});break;}case 'ai':{const panel=$('[data-fs-ai-request]');panel.hidden=!panel.hidden;target.setAttribute('aria-expanded',String(!panel.hidden));break;}case 'ai-open':await openAI();break;case 'svg':case 'png':case 'txt':case 'copy-svg':busy=true;target.disabled=true;await exportFile(target.dataset.fsAction);break;}}catch(e){if(current())status(e.message||'操作未完成，请重试。',true);}finally{busy=false;if(current())target.disabled=false;}}
 container.addEventListener('click',click);
 editor.addEventListener('input',()=>setFormula(editor.value));
 editor.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();const target=$(`[data-fs-action="${event.shiftKey?'redo':'undo'}"]`);if(!target.disabled)target.click();}});
 // Keep selection when a toolbar item is pressed. Inserting never rebuilds the editor.
 container.addEventListener('mousedown',event=>{if(event.target.closest('[data-fs-template],[data-fs-token]'))event.preventDefault();});
 $('[data-fs-requirements]').addEventListener('input',event=>{requirements=event.target.value;onChange(state());schedule();job?.inputChanged?.();});
 $('[data-fs-subject]').onchange=event=>{subject=event.target.value;categories();renderTemplates();};$('[data-fs-level]').onchange=event=>{level=event.target.value;renderTemplates();};$('[data-fs-category]').onchange=event=>{category=event.target.value;renderTemplates();};$('[data-fs-search]').oninput=event=>{query=event.target.value;renderTemplates();};
 $('[data-fs-font]').onchange=event=>{font=event.target.value;void preview();};$('[data-fs-size]').onchange=event=>{size=Number(event.target.value);$('[data-fs-preview]').style.setProperty('--formula-size',size+'px');};$('[data-fs-ink]').oninput=event=>{ink=event.target.value;void preview();};
 categories();renderSymbols();renderTemplates();$('[data-fs-count]').textContent=`${formula.length} / 2000`;void preview();
 return{getState:state,capture:state,hasWork:()=>formula!==savedFormula||!!job?.getState?.().itemId,dispose(){if(!alive)return;if(current())persist();alive=false;sequence++;win.clearTimeout(timer);ocr?.dispose();job?.dispose();container.removeEventListener('click',click);}};
}
